/* DVZ Shoutbox */
#shoutbox {
	margin-bottom: 10px;
	border: solid 1px white;
}

#shoutbox .head {
	background: #3F5B1D;
	color: #fff;
	padding: 8px;
}

#shoutbox.front .head {
 cursor: pointer;
}

#shoutbox .head .right {
	color: #fff;
	float: right;
	margin: 0;
	
	font-size: 13px;
}

#shoutbox > .head > .right > a {
 color: white;
}


}

#shoutbox.collapsed .head {
 opacity: 0.6;
}

#shoutbox.collapsed .body {
 display: none;
}

#shoutbox .panel {
	border-top: solid 2px rgba(0,0,0,0.1);
}

#shoutbox input.text {
 margin: 0; padding: 10px 8px; width: 100%; box-sizing: border-box; border: none; box-shadow: inset 0 2px 4px rgba(0,0,0,0.08); font-family: Arial, sans-serif; font-size: 12px; color: #000;
}

#shoutbox .minposts, #shoutbox .blocked {
 padding: 6px; font-size: 11px;
}

#shoutbox .panel.minposts {
}

#shoutbox .panel.blocked {
}

#shoutbox .panel p {
 margin: 0;
}

#shoutbox .window {
	border-top: solid 2px rgba(0,0,0,0.1);
	overflow-y: scroll;
}

#shoutbox .data {
	width: 100%;
	display: table;
	
	
	font-family: Arial, sans-serif;
	font-size: 12px;
}

#shoutbox.front .data {
 border-top: none;
}

#shoutbox .entry {
 display: table-row !important; width: 100%; transition: background-color 0.2s;
}

#shoutbox .entry:nth-child(even) {
 background-color: rgba(0,0,0,0.01);
}

#shoutbox .entry.new {
 background-color: rgba(255,255,100,0.1);
}

#shoutbox .entry:target {
 background-color: rgba(50,200,255,0.1);
}

#shoutbox .entry > div {
	border-bottom: dotted 1px white;
}

#shoutbox .entry:last-child > div {
 border-bottom: none;
}

#shoutbox .entry > div {
 display: table-cell; padding: 6px;
}

#shoutbox .avatar img {
 margin: 0 auto; vertical-align: middle; max-height: 20px; max-width: 20px; border: solid 1px rgba(255,255,255,0.1); box-shadow: 0 0 2px rgba(0,0,0,0.1); cursor: pointer;
}

#shoutbox .user {
 border-right: solid 1px rgba(0,0,0,0.05); text-align: right; white-space: nowrap;
}

#shoutbox .text {
	width: 100%;
	word-break: break-all;
	word-wrap: break-word;
}

#shoutbox .info {
	white-space: nowrap;
	text-align: right;
	
	font-size: 11px;
}

#shoutbox .entry.unread .info:before {
 display: inline-block; position: relative; top: -2px; margin-right: 10px; height: 4px; width: 4px; content: ''; background: rgba(255,100,0,0.8); border-radius: 10px;
}

#shoutbox .info a {
 color: inherit;
}

#shoutbox .mod {
	padding: 6px 8px;
	
	text-decoration: none;
	font-size: 9px;
	font-weight: bold;
}

#shoutbox .mod:nth-of-type(2) {
 margin-right: 5px; border-left: solid 1px rgba(0,0,0,0.1);
}

#shoutbox  .ip {
	margin-right: 10px;
}

.toggle, [id^="drop"] {
    display: none;
}

nav {
    background: #333;
    margin: 0;
    padding: 0;
}

nav::after {
    clear: both;
    content: "";
    display: table;
}

nav ul {
    list-style: outside none none;
    margin: 0;
    padding: 0;
    position: relative;
}

nav ul li {
    border-left: 1px solid #555;
    display: inline-block;
    float: left;
    margin: 0;
}

nav a {
	background: #222;
	color: #000;
	display: block;
	padding: 10px 15px;

	text-decoration: none;
	font-family: Helvetica,Arial,Verdana,sans-serif;
	font-size: 12px;
}

nav ul li ul li:hover {
    background: #444 none repeat scroll 0 0;
}

nav a:hover {
    background-color: #000000;
}

nav ul ul {
    display: none;
    position: absolute;
    top: 35px;
}

nav ul li:hover > ul {
    display: inherit;
}

nav ul ul li {
    display: list-item;
    float: none;
    position: relative;
    width: 170px;
}

nav ul ul ul li {
    left: 170px;
    position: relative;
    top: -60px;
}

nav ul li > a::after {
    content: " ";
    display: inline;
    font-family: fontawesome;
}

nav ul li > a:only-child::after {
    content: "";
}

@media all and (max-width: 768px) {
nav {
    margin: 0;
}

.toggle + a, .menu {
    display: none;
}

.toggle {
    background: #333;
    border: medium none;
    color: #ffffff;
    display: block;
    font-family: Helvetica,Arial,Verdana,sans-serif;
    font-size: 12px;
    padding: 10px 15px;
    text-decoration: none;
}

.toggle:hover {
    background-color: #000000;
}

[id^="drop"]:checked + ul {
    display: block;
}

nav ul li {
    display: block;
    width: 100%;
}

nav ul ul .toggle, nav ul ul a {
    padding: 0 40px;
}

nav ul ul ul a {
    padding: 0 80px;
}

nav a:hover, nav ul ul ul a {
    background-color: #000000;
}

nav ul li ul li .toggle, nav ul ul a, nav ul ul ul a {
	color: #000;
	padding: 10px 15px;

	font-size: 12px;
}

nav ul li ul li .toggle, nav ul ul a {
    background-color: #212121;
}

nav ul ul {
	color: #000;
	float: none;
	position: static;
}

nav ul ul li:hover > ul, nav ul li:hover > ul {
    display: none;
}

nav ul ul li {
    display: block;
    width: 100%;
}

nav ul ul ul li {
    position: static;
}


}

@media all and (max-width: 330px) {
nav ul li {
    display: block;
    width: 94%;
}


}

@media only screen and (min-width: 769px) {
nav ul {
    margin-left: 8%;
}

nav ul ul {
    margin-left: 0;
}


}

tr td.trow1:first-child,
tr td.trow2:first-child,
tr td.trow_shaded:first-child {
	border-left: 0;
}

tr td.trow1:last-child,
tr td.trow2:last-child,
tr td.trow_shaded:last-child {
	border-right: 0;
}

.tborder {
	-moz-border-radius: 7px;
	-webkit-border-radius: 7px;
	border-radius: 7px;
}

.tborder tbody tr:last-child > td {
	border-bottom: 0;
}

.tborder tbody tr:last-child > td:first-child {
	-moz-border-radius-bottomleft: 6px;
	-webkit-border-bottom-left-radius: 6px;
	border-bottom-left-radius: 6px;
}

.tborder tbody tr:last-child > td:last-child {
	-moz-border-radius-bottomright: 6px;
	-webkit-border-bottom-right-radius: 6px;
	border-bottom-right-radius: 6px;
}

.thead {
	-moz-border-radius-topleft: 6px;
	-moz-border-radius-topright: 6px;
	-webkit-border-top-left-radius: 6px;
	-webkit-border-top-right-radius: 6px;
	border-top-left-radius: 6px;
	border-top-right-radius: 6px;
}

.thead_collapsed {
	-moz-border-radius-bottomleft: 6px;
	-moz-border-radius-bottomright: 6px;
	-webkit-border-bottom-left-radius: 6px;
